CREATE TABLE carrier_tender_response_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,tender_attempt_id uuid NOT NULL REFERENCES carrier_tender_attempts(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),UNIQUE(company_id,tender_attempt_id));
CREATE TABLE carrier_tender_response_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,tender_attempt_id uuid NOT NULL REFERENCES carrier_tender_attempts(id) ON DELETE CASCADE,provider_event_id text NOT NULL,response text NOT NULL CHECK(response IN('accepted','rejected')),source text NOT NULL CHECK(source IN('secure_link','signed_webhook')),payload_hash text,response_note text,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,processing_status text NOT NULL DEFAULT 'received' CHECK(processing_status IN('received','processed','duplicate','late','invalid')),UNIQUE(company_id,provider_event_id));
CREATE FUNCTION resolve_carrier_tender_token(p_hash text) RETURNS TABLE(token_id uuid,company_id uuid,tender_attempt_id uuid,attempt_number integer,carrier_service_id uuid,carrier_name text,service_level text,order_no text,warehouse_name text,store_name text,shipment_units numeric,response_due_at timestamptz,expires_at timestamptz,status text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$SELECT k.id,k.company_id,t.id,t.attempt_number,t.carrier_service_id,c.name,c.service_level,o.order_no,w.name,coalesce(s.name,o.customer_name),coalesce((SELECT sum(quantity) FROM sales_order_lines WHERE order_id=o.id),0),t.response_due_at,k.expires_at,t.status FROM carrier_tender_response_tokens k JOIN carrier_tender_attempts t ON t.id=k.tender_attempt_id JOIN carrier_services c ON c.id=t.carrier_service_id JOIN order_carrier_assignments a ON a.id=t.assignment_id JOIN sales_orders o ON o.id=a.order_id JOIN warehouses w ON w.id=o.warehouse_id LEFT JOIN requesting_stores s ON s.id=o.store_id WHERE k.token_hash=p_hash AND k.used_at IS NULL AND k.revoked_at IS NULL AND k.expires_at>now()$$;
ALTER TABLE carrier_tender_response_tokens ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_response_tokens FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_response_events ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_response_events FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_carrier_tender_response_tokens ON carrier_tender_response_tokens USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_tender_response_events ON carrier_tender_response_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);REVOKE ALL ON FUNCTION resolve_carrier_tender_token(text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION resolve_carrier_tender_token(text) TO stockflow_app;GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_tender_response_tokens,carrier_tender_response_events TO stockflow_app;CREATE INDEX carrier_tender_response_expiry_idx ON carrier_tender_response_tokens(expires_at) WHERE used_at IS NULL AND revoked_at IS NULL;CREATE INDEX carrier_tender_response_attempt_idx ON carrier_tender_response_events(company_id,tender_attempt_id,received_at DESC);
